(() => {
  if ((document.documentElement.dataset.motion ? document.documentElement.dataset.motion === 'reduced' : matchMedia('(prefers-reduced-motion: reduce)').matches) || document.documentElement.dataset.layout === 'reader' || navigator.connection?.saveData || location.hash || document.hidden) return;
  const root = document.documentElement;
  root.classList.add('loader-running');
  window.loaderBootTimeout = setTimeout(() => {
    root.classList.remove('loader-running');
    root.dataset.loaderDone = 'true';
    document.dispatchEvent(new CustomEvent('loader:done'));
  }, 9000);
})();
